(6234591, 921193, 94815, '<td valign="top">Withe the model and cat, this could be a goof on Manet''s "Olympia" painting. Critical missing elements: direct gaze into the camera and someone delivering flowers. 6 but could have been better.</td>', 'Withe the model and cat, this could be a goof on Manet''s "Olympia" painting. Critical missing elements: direct gaze into the camera and someone delivering flowers. 6 but could have been better.', '2010-11-26 20:33:04.000000', NULL, 1),
(6234596, 921406, 109227, '<td valign="top">Love it; top three I think.  Wonderful black and white converstion and the expression is priceless.</td>', 'Love it; top three I think.  Wonderful black and white converstion and the expression is priceless.', '2010-11-26 20:46:42.000000', NULL, 1),
(6234597, 920996, 109227, '<td valign="top">Nicely done; one of the top picks I think.  Nice processing.  Would like to see his eyes open more, but does not detract.</td>', 'Nicely done; one of the top picks I think.  Nice processing.  Would like to see his eyes open more, but does not detract.', '2010-11-26 20:48:08.000000', NULL, 1),
(6234598, 921192, 109227, '<td valign="top">Love this one; processing is great and I like the grain.  10</td>', 'Love this one; processing is great and I like the grain.  10', '2010-11-26 20:48:52.000000', NULL, 1),
(6234599, 921227, 109227, '<td valign="top">Hand written letters have really become vintage.  Nice job.</td>', 'Hand written letters have really become vintage.  Nice job.', '2010-11-26 20:49:44.000000', NULL, 1),
(6234600, 921255, 109227, '<td valign="top">One of my favorites of the challenge.  Nice B&amp;W conversion and great clarity.</td>', 'One of my favorites of the challenge.  Nice B&W conversion and great clarity.', '2010-11-26 20:50:28.000000', NULL, 1),
(6234601, 921280, 109227, '<td valign="top">Beautiful image.</td>', 'Beautiful image.', '2010-11-26 20:50:41.000000', NULL, 1),
(6234765, 920953, 100831, '<td valign="top">excellent! I want to play now.</td>', 'excellent! I want to play now.', '2010-11-26 23:29:08.000000', NULL, 1),
(6234914, 920871, 64086, '<td valign="top">Like a visitor from another planet. I really like the selective color and the B&amp;W really brings out the contrasting texture of the ground and the trees in the background. Fantastic photo.</td>', 'Like a visitor from another planet. I really like the selective color and the B&W really brings out the contrasting texture of the ground and the trees in the background. Fantastic photo.', '2010-11-27 07:08:13.000000', NULL, 1),
(6234916, 920938, 64086, '<td valign="top">Wow! The focus/DOF are so perfect. I love the soft edges and the inclusion  of the photo on the wall. Amazing work.</td>', 'Wow! The focus/DOF are so perfect. I love the soft edges and the inclusion  of the photo on the wall. Amazing work.', '2010-11-27 07:11:51.000000', NULL, 1),
(6234917, 921060, 64086, '<td valign="top">Has a real vintage feel to it and the processing is perfect. Great photo.</td>', 'Has a real vintage feel to it and the processing is perfect. Great photo.', '2010-11-27 07:13:19.000000', NULL, 1),
(6234925, 920938, 57447, '<td valign="top">Interesting.</td>', 'Interesting.', '2010-11-27 07:48:29.000000', NULL, 1),
(6235054, 921370, 64086, '<td valign="top">Beautiful still life. I can feel the dust and warmth of the sun.</td>', 'Beautiful still life. I can feel the dust and warmth of the sun.', '2010-11-27 11:21:20.000000', NULL, 1),
(6235573, 920940, 66384, '<td valign="top">I really like the light and angles in this. I like the warm colors too.</td>', 'I really like the light and angles in this. I like the warm colors too.', '2010-11-27 23:48:35.000000', NULL, 1),
(6235577, 921023, 66384, '<td valign="top">Great vintage treatment of a vintage subject.</td>', 'Great vintage treatment of a vintage subject.', '2010-11-27 23:50:14.000000', NULL, 1),
(6235586, 921151, 66384, '<td valign="top">Beautiful processing.</td>', 'Beautiful processing.', '2010-11-27 23:55:02.000000', NULL, 1),
(6235590, 921284, 66384, '<td valign="top">You nailed this challenge!!!</td>', 'You nailed this challenge!!!', '2010-11-27 23:55:59.000000', NULL, 1),
(6235593, 921102, 66384, '<td valign="top">Excellent. The picture in the reflection is just as vintage as the items behind the window.</td>', 'Excellent. The picture in the reflection is just as vintage as the items behind the window.', '2010-11-27 23:59:34.000000', NULL, 1),
(6235594, 920996, 66384, '<td valign="top">Right off the cover of the Saturday Evening Post! Excellent.</td>', 'Right off the cover of the Saturday Evening Post! Excellent.', '2010-11-28 00:02:57.000000', NULL, 1),
(6235595, 921191, 66384, '<td valign="top">The ashtray is a good addition.</td>', 'The ashtray is a good addition.', '2010-11-28 00:05:32.000000', NULL, 1),
(6235609, 921342, 66384, '<td valign="top">I don''t rate on borders, but I think these modern style borders detract from the excellent vintage image. Beautiful portrait.</td>', 'I don''t rate on borders, but I think these modern style borders detract from the excellent vintage image. Beautiful portrait.', '2010-11-28 00:20:07.000000', NULL, 1),
(6235615, 920967, 66384, '<td valign="top">Gorgeous! Too bad about the Dunkin Donuts sign.</td>', 'Gorgeous! Too bad about the Dunkin Donuts sign.', '2010-11-28 00:23:54.000000', NULL, 1),
