INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6235766, 921191, 69324, '<td valign="top">Well thought out.</td>', 'Well thought out.', '2010-11-28 06:26:13.000000', NULL, 1),
(6235771, 921189, 69324, '<td valign="top">Looks like someone got their moneys worth out of these</td>', 'Looks like someone got their moneys worth out of these', '2010-11-28 06:31:39.000000', NULL, 1),
(6235814, 921370, 69324, '<td valign="top">Very nicely done, love all the dust.</td>', 'Very nicely done, love all the dust.', '2010-11-28 08:44:42.000000', NULL, 1),
(6235817, 920866, 69324, '<td valign="top">Nice job with the hair.</td>', 'Nice job with the hair.', '2010-11-28 08:48:20.000000', NULL, 1),
(6235823, 921226, 69324, '<td valign="top">Very fine composition.</td>', 'Very fine composition.', '2010-11-28 09:02:26.000000', NULL, 1),
(6235828, 921002, 69324, '<td valign="top">Very touching and poignant scene, hope you''re justly rewarded. 10</td>', 'Very touching and poignant scene, hope you''re justly rewarded. 10', '2010-11-28 09:07:24.000000', NULL, 1),
(6235845, 921063, 114225, '<td valign="top">Very well done. I like the composition, how it leads the eyes through the photo. And the processing really adds to the feel.</td>', 'Very well done. I like the composition, how it leads the eyes through the photo. And the processing really adds to the feel.', '2010-11-28 10:03:17.000000', NULL, 1),
(6235846, 921215, 114225, '<td valign="top">Nice find. Good details and colors in here. I''m actually not so sure about the all black background. Seems to take a bit away from the vintage feel.</td>', 'Nice find. Good details and colors in here. I''m actually not so sure about the all black background. Seems to take a bit away from the vintage feel.', '2010-11-28 10:04:43.000000', NULL, 1),
(6235849, 921463, 114225, '<td valign="top">Interesting how each bottle seems to have a different amount of liquid in it. Nice use of muted colors, that adds to the vintage feel. I do wish there were fewer reflections in the bottles.</td>', 'Interesting how each bottle seems to have a different amount of liquid in it. Nice use of muted colors, that adds to the vintage feel. I do wish there were fewer reflections in the bottles.', '2010-11-28 10:05:56.000000', NULL, 1),
(6235853, 920652, 114225, '<td valign="top">A good subject for this challenge, but the photo itself doesn''t impress me.Too many blown highlighters, no details in the shadows, and distracting background elements.</td>', 'A good subject for this challenge, but the photo itself doesn''t impress me.Too many blown highlighters, no details in the shadows, and distracting background elements.', '2010-11-28 10:10:41.000000', NULL, 1),
(6235858, 921140, 114225, '<td valign="top">Cute setup, and very nice processing for this challenge. I like your attention to details, even the hair seems to fit the time period.</td>', 'Cute setup, and very nice processing for this challenge. I like your attention to details, even the hair seems to fit the time period.', '2010-11-28 10:11:58.000000', NULL, 1),
(6235863, 921435, 114225, '<td valign="top">This photo has a really nice subject for this challenge, but I''m just not liking the overall photo a ton. I think the high perspective is the biggest detraction for me here.</td>', 'This photo has a really nice subject for this challenge, but I''m just not liking the overall photo a ton. I think the high perspective is the biggest detraction for me here.', '2010-11-28 10:14:00.000000', NULL, 1),
(6235868, 921151, 114225, '<td valign="top">Nice job with this. I really enjoy how the perspective used drags your eyes through the photo. And the muted colors were a great choice.</td>', 'Nice job with this. I really enjoy how the perspective used drags your eyes through the photo. And the muted colors were a great choice.', '2010-11-28 10:16:42.000000', NULL, 1),
(6235870, 920894, 114225, '<td valign="top">Great idea for this challenge. I like the view of the old details of the vehicle. I think it could have even been better by bringing out more of the colors and details (I think this would be a great chance to use Topaz products).</td>', 'Great idea for this challenge. I like the view of the old details of the vehicle. I think it could have even been better by bringing out more of the colors and details (I think this would be a great chance to use Topaz products).', '2010-11-28 10:18:30.000000', NULL, 1),
(6235875, 920828, 114225, '<td valign="top">I''m a sucker for coffee photographs (am I addicted?) and this one is very well done. I am guessing some people don''t like the lighting, but I enjoy how it gives the feeling of an early morning cup.</td>', 'I''m a sucker for coffee photographs (am I addicted?) and this one is very well done. I am guessing some people don''t like the lighting, but I enjoy how it gives the feeling of an early morning cup.', '2010-11-28 10:20:21.000000', NULL, 1),
(6235880, 920980, 114225, '<td valign="top">I''m wondering if you are getting a bunch of low votes from quick voters. I gave myself enough time to appreciate this photograph, as my first reaction was definitely (yuck). But looking at it more, the use of leading lines, the balance, and even the reddish processing is all very nice.</td>', 'I''m wondering if you are getting a bunch of low votes from quick voters. I gave myself enough time to appreciate this photograph, as my first reaction was definitely (yuck). But looking at it more, the use of leading lines, the balance, and even the reddish processing is all very nice.', '2010-11-28 10:22:42.000000', NULL, 1),
(6235882, 921437, 114225, '<td valign="top">Great idea for this challenge. I think what''s really hurting this photo in my eye is having the two main elements lined up. I would have liked to see the rock formation off to one side, with the teepee to the other (or some variation of that).</td>', 'Great idea for this challenge. I think what''s really hurting this photo in my eye is having the two main elements lined up. I would have liked to see the rock formation off to one side, with the teepee to the other (or some variation of that).', '2010-11-28 10:24:32.000000', NULL, 1),
(6235887, 921227, 114225, '<td valign="top">I really enjoy this photo. Especially with the upper right cancellation asks to always use ZIP codes, with the main envelope completely omits it.</td>', 'I really enjoy this photo. Especially with the upper right cancellation asks to always use ZIP codes, with the main envelope completely omits it.', '2010-11-28 10:27:31.000000', NULL, 1),
(6235888, 921392, 122896, '<td valign="top">Very nice!</td>', 'Very nice!', '2010-11-28 10:28:00.000000', NULL, 1),
(6235890, 921225, 114225, '<td valign="top">Great idea, and I really like the composition used. However, the blown highlights on the tops of the bails of hay is really distracting to me.</td>', 'Great idea, and I really like the composition used. However, the blown highlights on the tops of the bails of hay is really distracting to me.', '2010-11-28 10:28:45.000000', NULL, 1),
(6235891, 921193, 122896, '<td valign="top">I love this classic piece of work! 8</td>', 'I love this classic piece of work! 8', '2010-11-28 10:28:49.000000', NULL, 1),
(6235894, 921206, 114225, '<td valign="top">Cute idea of using the old wheel as a frame. It''s really quite unfortunate that the metal grate is so visible, that''s taking away from the vintage feel.</td>', 'Cute idea of using the old wheel as a frame. It''s really quite unfortunate that the metal grate is so visible, that''s taking away from the vintage feel.', '2010-11-28 10:31:46.000000', NULL, 1),
(6235896, 920866, 114225, '<td valign="top">Excellently executed photo. The props, clothing, and makeup are 100% pin-up.</td>', 'Excellently executed photo. The props, clothing, and makeup are 100% pin-up.', '2010-11-28 10:32:48.000000', NULL, 1),
(6235900, 921392, 114225, '<td valign="top">Excellent! Great use of perspective, and the details are quite fabulous. Looks like you used some selective desaturation, which was a great choice for this (not to mention very well done).</td>', 'Excellent! Great use of perspective, and the details are quite fabulous. Looks like you used some selective desaturation, which was a great choice for this (not to mention very well done).', '2010-11-28 10:35:54.000000', NULL, 1),
(6235924, 921428, 16106, '<td valign="top">I love the mood and colors here; Ominous framing and shadow; I just wish he still had his tail. My pick for a ribbon</td>', 'I love the mood and colors here; Ominous framing and shadow; I just wish he still had his tail. My pick for a ribbon', '2010-11-28 10:56:39.000000', NULL, 1),
(6235928, 920996, 16106, '<td valign="top">Nice Norman Rockwell feel here, the highlights on the shirt are a bit blown which is unfortunate, but the subject and feel make up for it. Ought to ribbon.</td>', 'Nice Norman Rockwell feel here, the highlights on the shirt are a bit blown which is unfortunate, but the subject and feel make up for it. Ought to ribbon.', '2010-11-28 10:58:23.000000', NULL, 1),
(6235932, 921392, 16106, '<td valign="top">A lovely combination of subject matter and technique, some may knock you for using a bit too much processing, but I think it matches the mood. My top pick.</td>', 'A lovely combination of subject matter and technique, some may knock you for using a bit too much processing, but I think it matches the mood. My top pick.', '2010-11-28 11:01:05.000000', NULL, 1),
(6235933, 921290, 16106, '<td valign="top">Interesting how many good shots use offcentered framing this week after that challenge, and use it well. The tones seem a bit soft, but the mood which that softness sets is lovely and the light is perfect.</td>', 'Interesting how many good shots use offcentered framing this week after that challenge, and use it well. The tones seem a bit soft, but the mood which that softness sets is lovely and the light is perfect.', '2010-11-28 11:03:23.000000', NULL, 1),
(6235934, 920652, 16106, '<td valign="top">A bit more sharpening in post processing would have gone a long way with this image, we are so used to super sharp car advertising images that the softness here will really hurt your score. Nice light used well to show off the car''s shape.</td>', 'A bit more sharpening in post processing would have gone a long way with this image, we are so used to super sharp car advertising images that the softness here will really hurt your score. Nice light used well to show off the car''s shape.', '2010-11-28 11:07:20.000000', NULL, 1),
(6235935, 920754, 16106, '<td valign="top">With this subtle a subject, the dodge and burn here is too heavy handed and over done for me, a lot of the texture of the trunk has been bleached out</td>', 'With this subtle a subject, the dodge and burn here is too heavy handed and over done for me, a lot of the texture of the trunk has been bleached out', '2010-11-28 11:09:21.000000', NULL, 1),
(6235938, 921222, 16106, '<td valign="top">There is alot of grain for a studio still life, but I do like the little portrait of your self and the rest of the room in the reflection on the bottle.</td>', 'There is alot of grain for a studio still life, but I do like the little portrait of your self and the rest of the room in the reflection on the bottle.', '2010-11-28 11:11:14.000000', NULL, 1),
(6235943, 921242, 16106, '<td valign="top">This has a lovely balance in the frame, but for me. its connection to the challenge is rather tenuous.</td>', 'This has a lovely balance in the frame, but for me. its connection to the challenge is rather tenuous.', '2010-11-28 11:12:43.000000', NULL, 1),
(6235976, 921370, 16106, '<td valign="top">Lovely balance of both color and massing in the frame.</td>', 'Lovely balance of both color and massing in the frame.', '2010-11-28 11:24:20.000000', NULL, 1),
(6236030, 921409, 67258, '<td valign="top">Not quite sure that the Police, the Rolling Stones, or the Beatles truly come under the category of Americana, but that aside, a good entry for the challenge.</td>', 'Not quite sure that the Police, the Rolling Stones, or the Beatles truly come under the category of Americana, but that aside, a good entry for the challenge.', '2010-11-28 12:13:17.000000', NULL, 1),
(6236085, 921176, 82104, '<td valign="top">I cannot see where this falls in to  the category of ''vintage''</td>', 'I cannot see where this falls in to  the category of ''vintage''', '2010-11-28 12:37:37.000000', NULL, 1),
(6236087, 921410, 82104, '<td valign="top">Nice idea but a flat</td>', 'Nice idea but a flat', '2010-11-28 12:38:11.000000', NULL, 1),
