(6236110, 920953, 82104, '<td valign="top">This is wonderful.</td>', 'This is wonderful.', '2010-11-28 12:49:29.000000', NULL, 1),
(6236114, 921190, 30861, '<td valign="top">That is the strangest distortion of the bowing arm...</td>', 'That is the strangest distortion of the bowing arm...', '2010-11-28 12:50:41.000000', NULL, 1),
(6236191, 921255, 76843, '<td valign="top">Love this........my Fave!</td>', 'Love this........my Fave!', '2010-11-28 13:51:32.000000', NULL, 1),
(6236194, 921370, 76843, '<td valign="top">Beautiful editing!</td>', 'Beautiful editing!', '2010-11-28 13:52:03.000000', NULL, 1),
(6236195, 920916, 76843, '<td valign="top">Absolutely love this! Very cool!</td>', 'Absolutely love this! Very cool!', '2010-11-28 13:52:47.000000', NULL, 1),
(6236197, 920739, 76843, '<td valign="top">One of my faves!</td>', 'One of my faves!', '2010-11-28 13:53:33.000000', NULL, 1),
(6236233, 921140, 41864, '<td valign="top">Gorgeous shot. Beautiful little model.</td>', 'Gorgeous shot. Beautiful little model.', '2010-11-28 14:22:21.000000', NULL, 1),
(6236558, 920996, 61725, '<td valign="top">This deserves a ribbon!</td>', 'This deserves a ribbon!', '2010-11-28 20:56:59.000000', NULL, 1),
(6236559, 921191, 61725, '<td valign="top">Love the fact that EVERYTHING in the pic is vintage...awesome arrangement!</td>', 'Love the fact that EVERYTHING in the pic is vintage...awesome arrangement!', '2010-11-28 20:57:37.000000', NULL, 1),
(6236683, 921428, 123348, '<td valign="top">cool image!</td>', 'cool image!', '2010-11-28 23:28:54.000000', NULL, 1),
(6236767, 920633, 52130, '<td valign="top">beautiful tones 9</td>', 'beautiful tones 9', '2010-11-29 00:31:33.000000', NULL, 1),
(6236770, 921428, 52130, '<td valign="top">this would look great hanging on a wall</td>', 'this would look great hanging on a wall', '2010-11-29 00:38:19.000000', NULL, 1),
