(6236905, 921151, 102534, '<td valign="top">would work well in B&amp;W</td>', 'would work well in B&W', '2010-11-29 04:56:53.000000', NULL, 1),
(6236910, 920996, 102534, '<td valign="top">Brilliant. Gotta be Blue :)</td>', 'Brilliant. Gotta be Blue :)', '2010-11-29 04:58:20.000000', NULL, 1),
(6236988, 921100, 123360, '<td valign="top">Wonderful Composition!</td>', 'Wonderful Composition!', '2010-11-29 06:21:51.000000', NULL, 1),
(6237006, 921392, 22689, '<td valign="top">Very elegant composition ! I really like the charming tones, they create a perfect vintage mood.<br/>my vote 8</td>', 'Very elegant composition ! I really like the charming tones, they create a perfect vintage mood.my vote 8', '2010-11-29 07:00:27.000000', NULL, 1),
(6237075, 921202, 124102, '<td valign="top">It makes me all warm and fuzzy!!!!!!!!</td>', 'It makes me all warm and fuzzy!!!!!!!!', '2010-11-29 08:03:00.000000', NULL, 1),
