(6237088, 921334, 111963, '<td valign="top">I have a couple of thoughts: the vignetting is too heavy for me, and the scene doesn''t really communicate vintage. Does look like a nice park though.</td>', 'I have a couple of thoughts: the vignetting is too heavy for me, and the scene doesn''t really communicate vintage. Does look like a nice park though.', '2010-11-29 08:21:19.000000', NULL, 1),
(6237089, 921023, 111963, '<td valign="top">Nice subject. I think the photo would be stronger without the vignetting though.</td>', 'Nice subject. I think the photo would be stronger without the vignetting though.', '2010-11-29 08:26:07.000000', NULL, 1),
(6237091, 920633, 111963, '<td valign="top">Yeah, you nailed it. 10.</td>', 'Yeah, you nailed it. 10.', '2010-11-29 08:27:43.000000', NULL, 1),
(6237093, 921250, 111963, '<td valign="top">Great portrait!</td>', 'Great portrait!', '2010-11-29 08:30:06.000000', NULL, 1),
